import sys

sys.setrecursionlimit(20000)

class Node:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def build_tree(nodes, target):
    if not nodes:
        return None, False

    root = Node(int(nodes[0]))
    queue = [root]
    idx = 1
    found_target = False

    if int(nodes[0]) == target:
        found_target = True

    while queue and idx < len(nodes):
        current = queue.pop(0)

        if idx < len(nodes):
            val = int(nodes[idx])
            if val == -1:
                current.left = None
            else:
                current.left = Node(val)
                if val == target:
                    found_target = True
                queue.append(current.left)
            idx += 1

        if idx < len(nodes):
            val = int(nodes[idx]) if idx < len(nodes) else -1
            if val == -1:
                current.right = None
            else:
                current.right = Node(val)
                if val == target:
                    found_target == True
                queue.append(current.right)
            idx += 1

    return root, found_target

def find_mirror(root, target):
    if root is None:
        return -1

    if root.data == target:
        return -1

    left_result = find_mirror(root.left, target)
    if left_result != -1:
        if root.right:
            return root.right.data
        return -1

    right_result = find_mirror(root.right, target)
    if right_result != -1:
        if root.left:
            return root.left.data
        return -1

    return -1

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    target = int(input_data[-1])

    nodes_str = input_data[1:-1]

    if n == 1:
        root = Node(int(nodes_str[0]))
        if root.data == target:
            print("-1")
        else:
            print("-1")
        return

    root, _ = build_tree(nodes_str, target)

    result = find_mirror(root, target)
    print(result)

if __name__ == "__main__":
    main()
